package com.strobingn.wildlifefieldops.ai

/**
 * 25 standalone field AI tools for Wildlife FieldOps.
 * Each tool is offline-first and produces a copyable action report.
 */
object FieldAIFeatures {
    data class Feature(
        val id: String,
        val title: String,
        val category: String,
        val purpose: String,
        val steps: List<String>,
        val output: String
