        Feature("squirrel_door", "Squirrel One-Way Planner", "Species", "Place one-ways so the animal leaves and cannot return.", listOf("Find the active hole (oil staining, chew, daylight).", "Mount the door flush; no side gaps.", "Seal every other hole the same day.", "Leave 3-5 days, then remove door and permanent-seal."), "Daytime activity = squirrel until proven otherwise. Check for a second litter before the final seal."),
        Feature("skunk_sop", "Skunk Handling SOP", "Species", "Reduce spray events and neighbor complaints.", listOf("Approach slowly; no flashlight in the face.", "Cover the trap with a towel before moving.", "Work decks and sheds with exclusion, not guesswork.", "Have deodorizer on the truck, not in the cab."), "Most skunk-under-deck jobs are exclusion plus one-way after confirming no kits. Do not pour ammonia as a plan."),
        Feature("groundhog_map", "Groundhog Burrow Mapper", "Species", "Map main and escape holes before trapping.", listOf("Find the fan-shaped dirt mound (main hole).", "Walk 10-30 ft for secondary exits.", "Set at the main hole; collapse unused holes only after capture.", "Repair foundation gaps the same day as removal."), "If you skip the escape hole, the animal is gone and the job looks like a miss."),
        Feature("bird_nest", "Bird Nest Timing", "Species", "Avoid illegal nest takes and failed exclusions.", listOf("Identify species before touching anything.", "Active migratory nests are generally protected.", "Install spikes, netting, or slope after the nest is inactive.", "Fix the attractant: vents, ledges, open soffits."), "If chicks are present, schedule a return window. Sell the exclusion now, install after fledging."),
        Feature("snake_safety", "Snake ID Safety", "Safety", "Treat unknown snakes as venomous until identified.", listOf("Do not pin or grab with bare hands.", "Photograph from a safe distance for ID.", "In NY, rattlesnakes are protected in many areas.", "Seal foundation gaps and rodent food sources."), "Most Hudson Valley yard calls are garter or milk snakes. Still use a hook/tongs. Sell rodent exclusion if mice are present."),
        Feature("opossum_notes", "Opossum Job Notes", "Species", "Fast, low-drama opossum removals.", listOf("They bluff. They rarely fight like raccoons.", "Check for young in the pouch before any relocation.", "Seal the crawl or deck the same visit.", "Do not market them as a disease emergency."), "If young are attached, delay or use a den-box protocol. Same-day exclusion prevents a callback."),
        Feature("wasp_tree", "Wasp / Bee Decision Tree", "Species", "Decide treat, refer, or exclude.", listOf("Honey bees in a wall: refer to a removal specialist when possible.", "Yellowjacket in the ground: treat at dusk, mark the hole.", "Paper wasp under soffit: scrape nest after treatment.", "Always close the cavity or it will be reused."), "Never treat a honey-bee wall and walk away. Comb and honey left behind create a worse follow-up."),
        Feature("attic_score", "Attic Inspection Scorecard", "Inspection", "Score an attic in five minutes.", listOf("Air quality / ammonia / dust (0-20).", "Droppings coverage (0-20).", "Insulation damage (0-20).", "Active entries visible (0-20).", "Electrical / fire / structural risk (0-20)."), "80+ = urgent cleanout + exclusion. 40-79 = exclusion now, cleanout quoted. Under 40 = monitor and seal secondaries."),
        Feature("crawl_hazards", "Crawlspace Hazard Checklist", "Safety", "Do not enter until the space is cleared.", listOf("Look for standing water, live wires, and needles.", "Check for gas, sewage, and low oxygen signs.", "Have a spotter. Phone on. Headlamp plus backup.", "Mark exit path before you crawl in."), "If you cannot see a second way out or the air is bad, decline entry and quote a conditioned-crawl or camera-only inspection."),
        Feature("roof_risk", "Roof Access Risk", "Safety", "Decide ladder, two-person, or no-go.", listOf("Pitch over 6/12 or wet moss = two-person minimum.", "Three-story or brittle slate = consider lift.", "Power lines within reach = stop.", "Frost or high wind = reschedule."), "A chimney-cap job is not worth a fall. Quote the lift. Document why you delayed."),
        Feature("daily_brief", "Daily Field Briefing", "Planning", "A one-page start-of-day brief.", listOf("List jobs by drive order, not by who called first.", "Flag heat, storms, and late-day roof work.", "Pre-load species-specific gear.", "Confirm access codes and dog/tenant notes."), "Start with the farthest AM wildlife-activity stop, then cluster repairs. Leave one emergency slot after 2 pm."),
        Feature("warranty_terms", "Warranty Language Helper", "Closeout", "Plain-language warranty that survives a callback.", listOf("State what is covered: listed openings only.", "State what is not: new storm damage, new construction gaps.", "State customer duties: no feeding wildlife, keep vents clear.", "State term and how to request a return visit."), "Example: We warrant the openings photographed on the invoice for 12 months against the listed species. New holes or customer-altered repairs are extra.")
    )
